// ============ UTILITIES ============
function toast(m,t) { const c=document.getElementById('toast-container'); if(!c)return; const i={success:'✅',error:'❌',warning:'⚠️',info:'ℹ️'}; const e=document.createElement('div'); e.className='toast '+(t||'info'); e.textContent=(i[t]||'')+' '+m; c.appendChild(e); setTimeout(()=>{e.style.opacity='0';e.style.transition='opacity 0.3s';setTimeout(()=>e.remove(),300);},3000); }
function fmt(a) { if(!a)return'$0.00'; return'$'+parseFloat(a).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }
function timeAgo(ts) { if(!ts)return''; const d=ts.toDate?ts.toDate():new Date(ts); const s=Math.floor((Date.now()-d)/1000); if(s<60)return'now'; if(s<3600)return Math.floor(s/60)+'m'; if(s<86400)return Math.floor(s/3600)+'h'; return Math.floor(s/86400)+'d'; }
function genId(p) { return(p||'id')+'_'+Date.now()+'_'+Math.random().toString(36).substr(2,9); }
function openModal(c) { const mc=document.getElementById('modal-content'),m=document.getElementById('modal-container'); if(mc&&m){mc.innerHTML=c;m.style.display='flex';} }
function closeModal() { const m=document.getElementById('modal-container'); if(m)m.style.display='none'; }
function copyText(t) { if(navigator.clipboard)navigator.clipboard.writeText(t).then(()=>toast('Copied!','success')); else toast('Copy manually','warning'); }
async function refreshProfile() { if(!APP.user||!db)return; const doc=await db.collection('users').doc(APP.user.uid).get(); if(doc.exists)APP.profile=doc.data(); }
async function detectCountry() { try{const r=await fetch('https://ipapi.co/json/');const d=await r.json();if(typeof getCountryByCode==='function'){const c=getCountryByCode(d.country_code);if(c){APP.country=c;APP.exchangeRate=typeof getExchangeRate==='function'?getExchangeRate(c.currency):1;}}}catch(e){} }
function genRefCode() { return'REF'+Math.random().toString(36).substring(2,8).toUpperCase(); }
function calcCommission(price,pct) { return(price*(pct||4))/100; }
function genStars(r) { const f=Math.floor(r),h=r%1>=0.5?1:0,e=5-f-h; return'⭐'.repeat(f)+(h?'✨':'')+'☆'.repeat(e); }

// ============ LOADER ============
function startLoader() { const fill=document.querySelector('.loader-progress-fill'),text=document.querySelector('.loader-percent'); if(!fill||!text)return null; let p=0; const t=setInterval(()=>{p+=Math.floor(Math.random()*8)+3;if(p>=90){p=90;clearInterval(t);}fill.style.width=p+'%';text.textContent=p+'%';},250); return t; }
function finishLoader(t) { if(t)clearInterval(t); const fill=document.querySelector('.loader-progress-fill'),text=document.querySelector('.loader-percent'); if(fill)fill.style.width='100%'; if(text)text.textContent='100%'; }
function hideLoader() { const l=document.getElementById('app-loader'),a=document.getElementById('app-container'); if(!l||!a)return; setTimeout(()=>{l.style.opacity='0';l.style.transition='opacity 0.5s';setTimeout(()=>{l.style.display='none';a.style.display='block';},500);},300); }

// ============ NAVIGATION ============
const ALL_SCREENS = ['onboarding','auth','account-type','setup-credentials','home','marketplace','product-detail','affiliate','advertisers','affiliate-install','checkout','orders','wallet','profile','store-setup','merchant','admin','settings','add-product','notifications','transactions','leaderboard','analytics','customerservice','disputes-manage'];
function goTo(screen,data) {
    if(!screen)return;
    if(APP.screen&&APP.screen!==screen){APP.prevScreen=APP.screen;APP.history.push(APP.screen);if(APP.history.length>50)APP.history.shift();}
    APP.screen=screen;
    ALL_SCREENS.forEach(s=>{const el=document.getElementById('screen-'+s);if(el)el.style.display='none';});
    const target=document.getElementById('screen-'+screen);
    if(target){target.style.display='block';const mc=target.querySelector('.main-content');if(mc)mc.scrollTop=0;updateNav(screen);loadScreenData(screen,data);document.title=screen.charAt(0).toUpperCase()+screen.slice(1).replace(/-/g,' ')+' - Shoplify';}
}
function goBack() { if(APP.history.length>0)goTo(APP.history.pop()); else{const d=APP.accountType==='admin'?'admin':APP.accountType==='customerservice'?'customerservice':'home';goTo(d);} }
function updateNav(screen) {
    document.querySelectorAll('.bottom-nav').forEach(nav=>{
        nav.querySelectorAll('.nav-item').forEach((item,i)=>{item.classList.remove('active');const map={home:0,marketplace:1,orders:2,affiliate:3,profile:4};if(map[screen]===i)item.classList.add('active');});
        const hide=['onboarding','auth','account-type','setup-credentials','checkout','product-detail','advertisers','affiliate-install','store-setup','add-product','settings','notifications','transactions','leaderboard','analytics','customerservice','disputes-manage'];
        nav.style.display=hide.includes(screen)?'none':'flex';
    });
}
function loadScreenData(screen,data) {
    setTimeout(()=>{
        switch(screen){case'home':loadHome();break;case'marketplace':loadMarketplace();break;case'product-detail':if(data)loadProductDetail(data);break;case'affiliate':loadAffiliateDashboard();break;case'advertisers':loadAdvertisers();break;case'affiliate-install':loadAffiliateBrowse();break;case'checkout':loadCheckout();break;case'orders':loadOrders();break;case'wallet':loadWallet();break;case'profile':loadProfile();break;case'store-setup':loadStoreSetup();break;case'merchant':loadMerchantDashboard();break;case'settings':loadSettings();break;case'add-product':loadAddProduct();break;case'notifications':loadNotifications();break;case'transactions':loadTransactions();break;case'leaderboard':loadLeaderboard();break;case'analytics':loadAnalytics();break;case'customerservice':loadCustomerService();break;case'disputes-manage':loadDisputesManage();break;case'admin':loadAdmin();break;}
    },200);
}

