async function addNotification(userId,title,message,icon,link) { if(!db)return; try{await db.collection('notifications').add({userId,title,message,icon:icon||'🔔',link:link||'',read:false,createdAt:firebase.firestore.FieldValue.serverTimestamp()});}catch(e){} }
async function loadNotifications() { if(!APP.user||!db)return;const screen=document.getElementById('screen-notifications');if(!screen)return;let mc=screen.querySelector('.main-content');if(!mc){mc=document.createElement('div');mc.className='main-content';screen.appendChild(mc);}try{const snap=await db.collection('notifications').where('userId','==',APP.user.uid).orderBy('createdAt','desc').limit(50).get();if(snap.empty){mc.innerHTML='<p style="text-align:center;color:#999;padding:40px;">No notifications</p>';return;}const batch=db.batch();snap.docs.forEach(doc=>{if(!doc.data().read)batch.update(db.collection('notifications').doc(doc.id),{read:true});});await batch.commit();const badge=document.getElementById('notif-badge');if(badge)badge.style.display='none';mc.innerHTML=snap.docs.map(doc=>{const n=doc.data();return`<div style="padding:14px;border-bottom:1px solid #f5f5f5;"><div style="display:flex;align-items:center;gap:10px;"><span style="font-size:24px;">${n.icon||'🔔'}</span><div style="flex:1;"><p style="font-weight:600;">${n.title}</p><p style="font-size:13px;color:#666;">${n.message}</p><p style="font-size:11px;color:#999;">${timeAgo(n.createdAt)}</p></div></div></div>`;}).join('');}catch(e){mc.innerHTML='<p style="text-align:center;color:#999;">Error</p>';} }
async function loadNotificationBadge() { if(!APP.user||!db)return;try{const snap=await db.collection('notifications').where('userId','==',APP.user.uid).where('read','==',false).limit(1).get();const badge=document.getElementById('notif-badge');if(badge){badge.style.display=snap.empty?'none':'flex';badge.textContent=snap.size;}}catch(e){} }

// ============ AUTH ============
function signInWithGoogle() {
    if(APP.loginRestricted){toast('Account restricted.','error');return;}
    const btn=document.querySelector('.btn-google');if(btn){btn.disabled=true;btn.innerHTML='<i class="fas fa-spinner fa-spin"></i> Connecting...';}
    if(!auth){toast('Please wait...','warning');if(btn)resetBtn(btn);return;}
    const provider=new firebase.auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});
    auth.signInWithPopup(provider).then(async result=>{
        APP.user=result.user;APP.authenticated=true;APP.loginAttempts=0;
        const userDoc=await db.collection('users').doc(result.user.uid).get();
        if(!userDoc.exists){if(btn)resetBtn(btn);goTo('account-type');}
        else{const profile=userDoc.data();APP.profile=profile;APP.accountType=profile.accountType||'customer';if(profile.loginRestrictedUntil&&profile.loginRestrictedUntil>Date.now()){APP.loginRestricted=true;auth.signOut();toast('Account restricted.','error');return;}if(profile.isSuspended){auth.signOut();toast('Account suspended.','error');return;}if(!profile.username||!profile.password){if(btn)resetBtn(btn);goTo('setup-credentials');return;}await saveUserProfile(result.user,profile);if(btn)resetBtn(btn);toast('Welcome back, '+(profile.displayName||profile.username)+'!','success');navigateToDashboard();}
    }).catch(err=>{if(btn)resetBtn(btn);APP.loginAttempts++;if(APP.loginAttempts>=5){APP.loginRestricted=true;const ru=Date.now()+3600000;if(APP.user)db.collection('users').doc(APP.user.uid).update({loginRestrictedUntil:ru});toast('Too many attempts. Restricted 1 hour.','error');return;}if(err.code==='auth/popup-closed-by-user')toast('Cancelled','warning');else if(err.code==='auth/popup-blocked')toast('Allow popups','error');else toast('Sign in failed','error');});
}
function loginWithCredentials() {
    if(APP.loginRestricted){toast('Account restricted.','error');return;}
    const username=document.getElementById('login-username')?.value?.trim();const password=document.getElementById('login-password')?.value?.trim();
    if(!username||!password){toast('Enter username and password','error');return;}
    db.collection('users').where('username','==',username).limit(1).get().then(async snap=>{
        if(snap.empty){APP.loginAttempts++;toast('Invalid credentials','error');return;}
        const doc=snap.docs[0];const profile=doc.data();
        if(profile.password!==password){APP.loginAttempts++;if(APP.loginAttempts>=5){const ru=Date.now()+3600000;db.collection('users').doc(doc.id).update({loginRestrictedUntil:ru});APP.loginRestricted=true;toast('Restricted 1 hour.','error');}else toast('Invalid credentials','error');return;}
        if(profile.loginRestrictedUntil&&profile.loginRestrictedUntil>Date.now()){APP.loginRestricted=true;toast('Account restricted.','error');return;}
        if(profile.isSuspended){toast('Account suspended.','error');return;}
        APP.loginAttempts=0;APP.authenticated=true;APP.profile=profile;APP.accountType=profile.accountType||'customer';APP.user={uid:doc.id,email:profile.email,displayName:profile.displayName};
        toast('Welcome back, '+profile.username+'!','success');navigateToDashboard();
    });
}
function resetBtn(btn){if(btn){btn.disabled=false;btn.innerHTML='<i class="fab fa-google"></i> Continue with Google';}}
async function saveUserProfile(user,profile){
    const data={uid:user.uid,email:user.email,displayName:user.displayName||user.email.split('@')[0],photoURL:user.photoURL||'',walletBalance:profile?.walletBalance||0,affiliateEarnings:profile?.affiliateEarnings||0,pendingEarnings:profile?.pendingEarnings||0,escrowBalance:profile?.escrowBalance||0,withdrawnBalance:profile?.withdrawnBalance||0,accountType:profile?.accountType||APP.accountType||'customer',isMerchant:profile?.isMerchant||false,isAffiliate:profile?.isAffiliate||false,isAmbassador:profile?.isAmbassador||false,isVerifiedMerchant:profile?.isVerifiedMerchant||false,isVerifiedAffiliate:profile?.isVerifiedAffiliate||false,merchantSubscription:profile?.merchantSubscription||null,affiliateSubscription:profile?.affiliateSubscription||null,advertiserSubscription:profile?.advertiserSubscription||null,bankAccounts:profile?.bankAccounts||[],suspensionCount:profile?.suspensionCount||0,isSuspended:profile?.isSuspended||false,storeTemplate:profile?.storeTemplate||null,storeActive:profile?.storeActive||false,storeName:profile?.storeName||'',username:profile?.username||'',password:profile?.password||'',theme:profile?.theme||'light',textSize:profile?.textSize||'medium',country:APP.country.code,countryFlag:APP.country.flag,currency:APP.country.currency,exchangeRate:APP.exchangeRate,totalSales:profile?.totalSales||0,totalRevenue:profile?.totalRevenue||0,referralCode:profile?.referralCode||genRefCode(),referredBy:profile?.referredBy||APP.referralCode||null,lastLogin:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()};
    if(!profile||!profile.createdAt)data.createdAt=firebase.firestore.FieldValue.serverTimestamp();
    await db.collection('users').doc(user.uid).set(data,{merge:true});
    if(data.referredBy&&(!profile||!profile.referralBonusPaid)){const snap=await db.collection('users').where('referralCode','==',data.referredBy).limit(1).get();if(!snap.empty){const ref=snap.docs[0];await db.collection('users').doc(ref.id).update({walletBalance:firebase.firestore.FieldValue.increment(CONFIG.referralBonus)});await db.collection('users').doc(user.uid).update({referralBonusPaid:true});await addNotification(ref.id,'Referral Bonus','You earned $'+CONFIG.referralBonus.toFixed(2)+'!','💰');}}
    APP.profile=data;
}
async function selectAccountType(type){
    if(!APP.user){toast('Sign in first','error');return;}APP.accountType=type;
    if(type==='merchant'){FlutterwaveCheckout({public_key:CONFIG.flutterwaveKey,tx_ref:'mer_'+Date.now(),amount:CONFIG.merchantPrice,currency:'USD',customer:{email:APP.user.email},callback:async function(res){if(res.status==='successful'){await db.collection('users').doc(APP.user.uid).update({accountType:type,isMerchant:true,merchantSubscription:'active',merchantSince:firebase.firestore.FieldValue.serverTimestamp()});APP.profile={...APP.profile,accountType:type,isMerchant:true,merchantSubscription:'active'};toast('✅ Merchant activated!','success');goTo('setup-credentials');}},onclose:()=>toast('Cancelled','warning')});}
    else if(type==='affiliate'){FlutterwaveCheckout({public_key:CONFIG.flutterwaveKey,tx_ref:'aff_'+Date.now(),amount:CONFIG.affiliatePrice,currency:'USD',customer:{email:APP.user.email},callback:async function(res){if(res.status==='successful'){await db.collection('users').doc(APP.user.uid).update({accountType:type,isAffiliate:true,affiliateSubscription:'active',affiliateSince:firebase.firestore.FieldValue.serverTimestamp()});APP.profile={...APP.profile,accountType:type,isAffiliate:true,affiliateSubscription:'active'};toast('✅ Affiliate activated!','success');goTo('setup-credentials');}},onclose:()=>toast('Cancelled','warning')});}
    else{await db.collection('users').doc(APP.user.uid).update({accountType:type});APP.profile={...APP.profile,accountType:type};goTo('setup-credentials');}
}
async function setupCredentials(){const username=document.getElementById('setup-username')?.value?.trim();const password=document.getElementById('setup-password')?.value?.trim();const cp=document.getElementById('setup-confirm-password')?.value?.trim();if(!username||username.length<3){toast('Username 3+ chars','error');return;}if(!password||password.length<6){toast('Password 6+ chars','error');return;}if(password!==cp){toast('Passwords dont match','error');return;}const exist=await db.collection('users').where('username','==',username).limit(1).get();if(!exist.empty&&exist.docs[0].id!==APP.user.uid){toast('Username taken','error');return;}await db.collection('users').doc(APP.user.uid).update({username,password});APP.profile={...APP.profile,username,password};toast('✅ Account ready!','success');await addNotification(APP.user.uid,'Welcome!','Account setup complete.','🎉');navigateToDashboard();}
function navigateToDashboard(){switch(APP.accountType){case'admin':goTo('admin');break;case'customerservice':goTo('customerservice');break;case'affiliate':goTo('affiliate');break;case'merchant':goTo('merchant');break;default:goTo('home');}}
function signOut(){if(!confirm('Sign out?'))return;if(auth){auth.signOut().then(()=>{APP.user=null;APP.profile=null;APP.authenticated=false;APP.accountType=null;APP.cart=[];localStorage.removeItem('shoplify_auth');goTo('onboarding');toast('Signed out','success');});}}

// ============ HOME ============
async function loadHome(){if(!APP.authenticated)return;await refreshProfile();const bal=document.getElementById('home-balance'),aff=document.getElementById('home-affiliate-earnings'),pen=document.getElementById('home-pending-earnings');if(bal)bal.textContent=fmt(APP.profile?.walletBalance||0);if(aff)aff.textContent=fmt(APP.profile?.affiliateEarnings||0);if(pen)pen.textContent=fmt(APP.profile?.pendingEarnings||0);const catC=document.getElementById('home-categories');if(catC)catC.innerHTML=CATEGORIES.map(c=>`<button class="category-chip" onclick="goTo('marketplace');setTimeout(()=>filterCat('${c}'),300);">${c}</button>`).join('');await loadFeatured();await loadSponsored();await loadNotificationBadge();}
async function loadFeatured(){const c=document.getElementById('home-featured-products');if(!c||!db)return;try{const snap=await db.collection('products').where('status','==','active').orderBy('totalSales','desc').limit(10).get();if(snap.empty){c.innerHTML='<p style="text-align:center;color:#999;padding:40px;">No products yet</p>';return;}c.innerHTML=snap.docs.map(d=>productCard({id:d.id,...d.data()})).join('');attachClicks(c);}catch(e){c.innerHTML='<p style="text-align:center;color:#999;">Error</p>';}}
async function loadSponsored(){const sec=document.getElementById('sponsored-products');if(!sec||!db)return;try{const snap=await db.collection('products').where('sponsored','==',true).where('status','==','active').limit(5).get();if(!snap.empty){sec.innerHTML='<div class="section"><div class="section-header"><h3 class="section-title">⭐ Sponsored</h3></div><div class="products-grid">'+snap.docs.map(d=>productCard({id:d.id,...d.data()})).join('')+'</div></div>';attachClicks(sec);}}catch(e){}}

// ============ PRODUCT CARD ============
function productCard(p){const img=p.images?.[0]||p.imageUrl||'app-icon.png';const flagged=p.merchantFlagged&&p.flaggedUntil&&p.flaggedUntil>Date.now();const verified=p.merchantVerified;return`<div class="product-card" data-id="${p.id}" style="cursor:pointer;position:relative;">${flagged?'<div style="position:absolute;top:8px;left:8px;background:#FF4444;color:#fff;padding:2px 8px;border-radius:10px;font-size:10px;z-index:1;">⚠️ Flagged</div>':''}${verified?'<div style="position:absolute;top:8px;right:8px;background:#0095F6;color:#fff;width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;z-index:1;font-size:12px;">✓</div>':''}<img src="${img}" class="product-card-image" onerror="this.src='app-icon.png'" loading="lazy"><div class="product-card-info"><p class="product-card-name">${p.name}</p><p class="product-card-price">${fmt(p.price)}</p>${p.commissionPercentage?'<p style="font-size:10px;color:#00C851;">+'+p.commissionPercentage+'%</p>':''}<p style="font-size:10px;color:#999;">Stock: ${p.stock||0}</p></div></div>`;}
function attachClicks(container){container.querySelectorAll('.product-card').forEach(card=>{card.addEventListener('click',function(){const id=this.dataset.id;if(id)goTo('product-detail',id);});});}
function renderCards(products,containerId){const c=document.getElementById(containerId);if(!c)return;if(!products.length){c.innerHTML='<p style="text-align:center;color:#999;padding:40px;">No products found</p>';return;}c.innerHTML=products.map(p=>productCard(p)).join('');attachClicks(c);}

// ============ MARKETPLACE ============
async function loadMarketplace(){const catC=document.getElementById('marketplace-categories'),prodC=document.getElementById('marketplace-products');if(catC)catC.innerHTML='<button class="category-chip active" onclick="filterCat(\'all\',this)">All</button>'+CATEGORIES.map(c=>`<button class="category-chip" onclick="filterCat('${c}',this)">${c}</button>`).join('');if(prodC&&db){db.collection('products').where('status','==','active').orderBy('createdAt','desc').limit(50).get().then(snap=>{if(snap.empty){prodC.innerHTML='<p style="text-align:center;color:#999;padding:40px;">No products</p>';return;}renderCards(snap.docs.map(d=>({id:d.id,...d.data()})),'marketplace-products');}).catch(()=>{prodC.innerHTML='<p style="text-align:center;color:#999;">Error</p>';});}}
function filterCat(cat,chip){document.querySelectorAll('.category-chip').forEach(c=>c.classList.remove('active'));if(chip)chip.classList.add('active');const ref=cat==='all'?db.collection('products').where('status','==','active'):db.collection('products').where('status','==','active').where('category','==',cat);ref.limit(50).get().then(snap=>{renderCards(snap.docs.map(d=>({id:d.id,...d.data()})),'marketplace-products');}).catch(()=>{});}
function filterMarket(){const term=(document.getElementById('marketplace-search')?.value||'').toLowerCase();document.querySelectorAll('#marketplace-products .product-card').forEach(card=>{const name=(card.querySelector('.product-card-name')?.textContent||'').toLowerCase();card.style.display=name.includes(term)?'':'none';});}

// ============ PRODUCT DETAIL ============
async function loadProductDetail(id){if(!id||!db)return;try{const doc=await db.collection('products').doc(id).get();if(!doc.exists){toast('Product not found','error');goBack();return;}const p={id:doc.id,...doc.data()};APP.selectedProduct=p;APP.quantity=1;APP.selectedColor=p.colors?.[0]||null;APP.selectedSize=p.sizes?.[0]||null;const c=document.getElementById('product-detail-content');if(!c)return;const imgs=p.images||[];const main=imgs[0]||'app-icon.png';const shareLink=CONFIG.baseUrl+'/p/'+p.id;const flagged=p.merchantFlagged&&p.flaggedUntil&&p.flaggedUntil>Date.now();const verified=p.merchantVerified;c.innerHTML=`<div>${p.videoUrl?`<video src="${p.videoUrl}" controls style="width:100%;border-radius:12px;margin-bottom:12px;"></video>`:''}${flagged?'<div style="background:#FFEBEE;padding:8px 12px;border-radius:8px;margin-bottom:8px;color:#C62828;font-size:13px;">⚠️ This merchant is currently flagged</div>':''}<img src="${main}" id="main-image" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px;">${imgs.length>1?`<div style="display:flex;gap:8px;margin-top:8px;overflow-x:auto;">${imgs.map((img,i)=>`<img src="${img}" style="width:60px;height:60px;border-radius:8px;object-fit:cover;cursor:pointer;border:2px solid ${i===0?'#FFD700':'transparent'};" onclick="document.getElementById('main-image').src='${img}';this.parentElement.querySelectorAll('img').forEach(t=>t.style.borderColor='transparent');this.style.borderColor='#FFD700';">`).join('')}</div>`:''}<div style="display:flex;align-items:center;gap:8px;margin:12px 0;"><h1 style="font-size:22px;flex:1;">${p.name}</h1>${verified?`<span style="background:#0095F6;color:#fff;width:24px;height:24px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:12px;" title="Verified Merchant">✓</span>`:''}</div><p style="font-size:28px;font-weight:800;color:#FFD700;">${fmt(p.price)}</p>${p.commissionPercentage?`<span style="display:inline-block;background:#E8F5E9;color:#2E7D32;padding:4px 12px;border-radius:12px;font-size:13px;margin:4px 0;">💰 Earn ${p.commissionPercentage}%</span>`:''}<p style="margin:8px 0;">📦 ${p.stock>0?p.stock+' in stock':'<span style="color:#FF4444;">Out of stock</span>'}</p><p style="color:#666;line-height:1.6;margin:8px 0;">${p.description||'No description'}</p>${p.colors?.length?`<div style="margin:12px 0;"><p style="font-weight:600;">Color: <span id="sel-color">${p.colors[0]}</span></p><div style="display:flex;gap:8px;">${p.colors.map((cl,i)=>`<div onclick="selectColor('${cl}',this)" style="width:36px;height:36px;border-radius:50%;background:${cl.toLowerCase()};border:3px solid ${i===0?'#FFD700':'#ddd'};cursor:pointer;"></div>`).join('')}</div></div>`:''}${p.sizes?.length?`<div style="margin:12px 0;"><p style="font-weight:600;">Size: <span id="sel-size">${p.sizes[0]}</span></p><div style="display:flex;gap:8px;">${p.sizes.map((s,i)=>`<button onclick="selectSize('${s}',this)" style="padding:8px 16px;border-radius:8px;cursor:pointer;background:${i===0?'#FFD700':'#f5f5f5'};color:${i===0?'#fff':'#333'};border:2px solid ${i===0?'#FFD700':'#ddd'};">${s}</button>`).join('')}</div></div>`:''}<div style="display:flex;align-items:center;gap:12px;margin:16px 0;"><button onclick="updateQty(-1)" style="width:40px;height:40px;border-radius:50%;border:2px solid #ddd;background:#fff;font-size:20px;cursor:pointer;">−</button><span id="qty" style="font-size:20px;font-weight:700;">1</span><button onclick="updateQty(1)" style="width:40px;height:40px;border-radius:50%;border:2px solid #ddd;background:#fff;font-size:20px;cursor:pointer;">+</button></div><div style="display:flex;gap:10px;margin-bottom:12px;"><button class="btn-gold" onclick="addToCart('${p.id}')" style="flex:1;" ${p.stock<=0?'disabled':''}><i class="fas fa-cart-plus"></i> Add to Cart</button><button class="btn-gold" onclick="buyNow('${p.id}')" style="flex:1;" ${p.stock<=0?'disabled':''}><i class="fas fa-bolt"></i> Buy Now</button></div><button class="btn-outline" onclick="shareProductLink('${shareLink}','${p.name}')" style="width:100%;margin-bottom:12px;"><i class="fas fa-share-alt"></i> Share Product</button>${p.reviews?.length?`<div style="border-top:1px solid #eee;padding-top:16px;margin-top:16px;"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;"><span style="font-size:32px;font-weight:800;color:#FFD700;">${p.avgRating||'0.0'}</span><div>${genStars(p.avgRating||0)}<p style="font-size:12px;color:#999;">${p.reviewCount||0} reviews</p></div></div>${p.reviews.slice(0,5).map(r=>`<div style="padding:10px 0;border-bottom:1px solid #f5f5f5;"><p style="font-weight:600;">${r.userName||'Anonymous'}</p>${genStars(r.rating)}<p style="color:#666;">${r.text}</p></div>`).join('')}</div>`:''}</div>`;}catch(e){console.error('Product detail error:',e);toast('Error loading product','error');}}
function selectColor(color,el){el.parentElement.querySelectorAll('div').forEach(d=>{d.style.borderColor='#ddd';});el.style.borderColor='#FFD700';const span=document.getElementById('sel-color');if(span)span.textContent=color;APP.selectedColor=color;}
function selectSize(size,el){el.parentElement.querySelectorAll('button').forEach(b=>{b.style.background='#f5f5f5';b.style.color='#333';b.style.borderColor='#ddd';});el.style.background='#FFD700';el.style.color='#fff';el.style.borderColor='#FFD700';const span=document.getElementById('sel-size');if(span)span.textContent=size;APP.selectedSize=size;}
function updateQty(change){const el=document.getElementById('qty');if(!el)return;let q=parseInt(el.textContent)+change;if(q<1)q=1;if(q>99)q=99;el.textContent=q;APP.quantity=q;}
function addToCart(pid){const p=APP.selectedProduct;if(!p)return;const item={productId:pid,name:p.name,price:p.price,image:p.images?.[0]||'',color:APP.selectedColor,size:APP.selectedSize,quantity:APP.quantity,total:p.price*APP.quantity};const idx=APP.cart.findIndex(i=>i.productId===pid&&i.color===APP.selectedColor&&i.size===APP.selectedSize);if(idx>=0){APP.cart[idx].quantity+=APP.quantity;APP.cart[idx].total=APP.cart[idx].price*APP.cart[idx].quantity;}else APP.cart.push(item);localStorage.setItem('shoplify_cart',JSON.stringify(APP.cart));toast('Added to cart ('+APP.cart.length+' items)','success');}
function buyNow(pid){addToCart(pid);goTo('checkout');}
function shareProductLink(link,name){if(navigator.share){navigator.share({title:name||'Shoplify Product',text:'Check out this product!',url:link}).catch(()=>{copyText(link);});}else{copyText(link);}}

// ============ AFFILIATE DASHBOARD ============
async function loadAffiliateDashboard(){if(!APP.authenticated)return;await refreshProfile();const c=document.getElementById('affiliate-content');if(!c)return;if(!APP.profile?.isAffiliate){c.innerHTML=`<div style="text-align:center;padding:40px;"><div class="subscription-banner"><i class="fas fa-link" style="font-size:48px;display:block;margin-bottom:12px;"></i><h3>Become an Affiliate</h3><p>Earn ${CONFIG.affiliateCommissionMin}-${CONFIG.affiliateCommissionMax}% commission.</p><p style="font-size:20px;font-weight:700;">$${CONFIG.affiliatePrice}/month</p><button class="btn-gold" onclick="selectAccountType('affiliate')" style="width:100%;">Subscribe Now</button></div></div>`;return;}const snap=await db.collection('affiliate_products').where('affiliateId','==',APP.user.uid).where('status','==','active').get();const products=snap.docs.map(d=>({id:d.id,...d.data()}));const tc=products.reduce((s,p)=>s+(p.clicks||0),0),tcv=products.reduce((s,p)=>s+(p.conversions||0),0);const isAmb=APP.profile?.isAmbassador||false,isVer=APP.profile?.isVerifiedAffiliate||false;c.innerHTML=`${isAmb?`<div style="background:linear-gradient(135deg,#B87333,#8B4513);color:#fff;padding:16px;border-radius:12px;margin-bottom:16px;text-align:center;"><span style="font-size:32px;">👑</span><h3 style="color:#FFD700;">Ambassador</h3><p>$${CONFIG.ambassadorReward}/month reward</p></div>`:''}<div class="affiliate-stats"><div class="affiliate-stat-card"><p style="font-size:24px;font-weight:800;color:#FFD700;">${fmt(APP.profile?.affiliateEarnings||0)}</p><p style="font-size:11px;">Earnings</p></div><div class="affiliate-stat-card"><p style="font-size:24px;font-weight:800;color:#FFBB33;">${fmt(APP.profile?.pendingEarnings||0)}</p><p style="font-size:11px;">Pending</p></div><div class="affiliate-stat-card"><p style="font-size:24px;font-weight:800;color:#00C851;">${fmt((APP.profile?.affiliateEarnings||0)-(APP.profile?.pendingEarnings||0))}</p><p style="font-size:11px;">Available</p></div></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px;"><div style="background:#fff;padding:12px;border-radius:12px;text-align:center;"><p style="font-size:20px;font-weight:700;">${tc}</p><p style="font-size:11px;color:#999;">Clicks</p></div><div style="background:#fff;padding:12px;border-radius:12px;text-align:center;"><p style="font-size:20px;font-weight:700;">${tcv}</p><p style="font-size:11px;color:#999;">Sales</p></div><div style="background:#fff;padding:12px;border-radius:12px;text-align:center;"><p style="font-size:20px;font-weight:700;">${tc?((tcv/tc)*100).toFixed(1):'0'}%</p><p style="font-size:11px;color:#999;">Rate</p></div></div><div style="display:flex;gap:10px;margin-bottom:16px;"><button class="btn-gold" onclick="goTo('affiliate-install')" style="flex:1;">🔍 Browse Products</button><button class="btn-gold" onclick="goTo('advertisers')" style="flex:1;">📢 Advertisers</button></div><div style="display:flex;gap:10px;margin-bottom:16px;"><button class="btn-gold" onclick="goTo('analytics')" style="flex:1;">📊 Analytics</button><button class="btn-gold" onclick="goTo('leaderboard')" style="flex:1;">🏆 Leaderboard</button></div>${isVer?`<div style="display:flex;align-items:center;gap:8px;justify-content:center;margin-bottom:12px;"><span style="background:#0095F6;color:#fff;width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;">✓</span><span style="color:#0095F6;font-weight:600;">Verified Affiliate</span></div>`:''}<h3 style="margin-bottom:12px;">My Products (${products.length})</h3>${products.length>0?products.map(p=>`<div class="affiliate-product-card"><img src="${p.productImage||'app-icon.png'}" style="width:70px;height:70px;border-radius:10px;"><div style="flex:1;"><p style="font-weight:600;">${p.productName}</p><p style="font-size:12px;color:#00C851;">${fmt(p.productPrice)} | +${p.commissionPercentage}%</p><p onclick="copyText('${p.affiliateLink}')" style="color:#33B5E5;font-size:11px;cursor:pointer;">📋 Copy Link</p><div style="display:flex;gap:8px;font-size:10px;color:#999;"><span>👁 ${p.clicks||0}</span><span>✅ ${p.conversions||0}</span><span>💰 ${fmt(p.totalCommission||0)}</span></div></div></div>`).join(''):'<p style="text-align:center;color:#999;">No products installed</p>'}<div style="background:#f9f9f9;border-radius:12px;padding:16px;margin-top:16px;text-align:center;"><h4>🎁 Refer & Earn</h4><p style="font-size:13px;color:#666;">Share code, earn $${CONFIG.referralBonus}/signup</p><p style="font-size:20px;font-weight:700;color:#FFD700;">${APP.profile?.referralCode||'N/A'}</p><button class="btn-small-gold" onclick="copyText('${CONFIG.baseUrl}?ref=${APP.profile?.referralCode||''}')">Copy Referral Link</button></div>`;}

// ============ ADVERTISERS PAGE ============
async function loadAdvertisers(){if(!APP.authenticated||!db)return;await refreshProfile();const c=document.getElementById('screen-advertisers');if(!c)return;let mc=c.querySelector('.main-content');if(!mc){mc=document.createElement('div');mc.className='main-content';c.appendChild(mc);}const hasSub=APP.profile?.advertiserSubscription==='active';if(!hasSub){mc.innerHTML=`<div style="text-align:center;padding:40px;"><i class="fas fa-ad" style="font-size:48px;color:#FFD700;display:block;margin-bottom:12px;"></i><h3>Advertiser Marketplace</h3><p style="color:#666;">Access verified advertisers for just $1/month</p><p style="font-size:20px;font-weight:700;color:#FFD700;">$${CONFIG.advertiserPrice}/month</p><p style="font-size:12px;color:#999;">Pay from wallet balance</p><button class="btn-gold mt-20" onclick="subscribeAdvertiser()" style="width:100%;">Subscribe Now</button></div>`;return;}mc.innerHTML='<h3>📢 Verified Advertisers</h3><p style="color:#666;margin-bottom:16px;">All advertisers are verified by Shoplify</p><div id="advertisers-list"><p style="text-align:center;color:#999;">Loading...</p></div>';try{const snap=await db.collection('advertisers').where('status','==','active').get();const container=document.getElementById('advertisers-list');if(snap.empty){container.innerHTML='<p style="text-align:center;color:#999;padding:40px;">No advertisers yet</p>';return;}container.innerHTML=snap.docs.map(doc=>{const a=doc.data();return`<div style="background:#fff;border-radius:12px;padding:16px;margin-bottom:12px;box-shadow:0 2px 8px rgba(0,0,0,0.05);"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;"><img src="${a.photoURL||'app-icon.png'}" style="width:60px;height:60px;border-radius:50%;object-fit:cover;border:2px solid #FFD700;"><div style="flex:1;"><div style="display:flex;align-items:center;gap:8px;"><h4>${a.name}</h4><span style="background:#0095F6;color:#fff;width:18px;height:18px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:10px;">✓</span></div><div style="color:#FFD700;">${genStars(a.rating||5)}</div></div></div><p style="color:#666;margin:8px 0;">${a.description||'Trusted advertising partner'}</p><div style="display:flex;align-items:center;gap:8px;padding:8px 12px;background:#f5f5f5;border-radius:8px;"><span style="font-size:24px;">${a.platformIcon||'📱'}</span><div><p style="font-weight:600;font-size:13px;">${a.platform||'Platform'}</p><p style="font-size:11px;color:#33B5E5;">@${a.handle||'handle'}</p></div></div><a href="${a.whatsappLink||'#'}" target="_blank" style="display:block;text-align:center;background:#25D366;color:#fff;padding:10px;border-radius:8px;text-decoration:none;margin-top:8px;font-weight:600;"><i class="fab fa-whatsapp"></i> Contact on WhatsApp</a></div>`;}).join('');}catch(e){document.getElementById('advertisers-list').innerHTML='<p style="text-align:center;color:#999;">Error loading advertisers</p>';}}
async function subscribeAdvertiser(){if(!APP.authenticated)return;const bal=APP.profile?.walletBalance||0;if(bal<CONFIG.advertiserPrice){toast('Insufficient balance. Please deposit.','error');goTo('wallet');return;}if(!confirm('Subscribe to Advertiser Marketplace for $'+CONFIG.advertiserPrice+'/month? Paid from wallet.'))return;await db.collection('users').doc(APP.user.uid).update({walletBalance:firebase.firestore.FieldValue.increment(-CONFIG.advertiserPrice),advertiserSubscription:'active',advertiserSince:firebase.firestore.FieldValue.serverTimestamp()});APP.profile={...APP.profile,walletBalance:bal-CONFIG.advertiserPrice,advertiserSubscription:'active'};toast('✅ Subscribed! Access granted.','success');loadAdvertisers();}

// ============ AFFILIATE BROWSE & INSTALL ============
async function loadAffiliateBrowse(){if(!APP.authenticated)return;const c=document.getElementById('affiliate-install-content');if(!c)return;c.innerHTML=`<div class="search-bar"><i class="fas fa-search"></i><input type="text" id="aff-search" placeholder="Search products to promote..." oninput="filterAffProducts()"></div><div class="categories-scroll" id="aff-categories">${CATEGORIES.map(cat=>`<button class="category-chip" onclick="filterAffCat('${cat}',this)">${cat}</button>`).join('')}</div><div class="products-grid" id="aff-products"></div>`;try{const snap=await db.collection('products').where('status','==','active').limit(50).get();const prods=snap.docs.map(d=>({id:d.id,...d.data()})).filter(p=>!p.merchantFlagged||p.flaggedUntil<Date.now());renderCards(prods,'aff-products');document.querySelectorAll('#aff-products .product-card').forEach(card=>{card.addEventListener('click',function(){const id=this.dataset.id;if(id)showInstallPrompt(id);});});}catch(e){}}
function filterAffProducts(){const term=(document.getElementById('aff-search')?.value||'').toLowerCase();document.querySelectorAll('#aff-products .product-card').forEach(card=>{const name=(card.querySelector('.product-card-name')?.textContent||'').toLowerCase();card.style.display=name.includes(term)?'':'none';});}
function filterAffCat(cat,chip){document.querySelectorAll('#aff-categories .category-chip').forEach(c=>c.classList.remove('active'));if(chip)chip.classList.add('active');db.collection('products').where('status','==','active').where('category','==',cat).limit(50).get().then(snap=>{renderCards(snap.docs.map(d=>({id:d.id,...d.data()})),'aff-products');document.querySelectorAll('#aff-products .product-card').forEach(card=>{card.addEventListener('click',function(){const id=this.dataset.id;if(id)showInstallPrompt(id);});});});}
async function showInstallPrompt(productId){const pDoc=await db.collection('products').doc(productId).get();const p=pDoc.data();openModal(`<div style="text-align:center;"><img src="${p.images?.[0]||'app-icon.png'}" style="width:100px;height:100px;border-radius:12px;margin-bottom:12px;"><h3>${p.name}</h3><p style="color:#FFD700;font-weight:700;">${fmt(p.price)}</p><p style="color:#00C851;">+${p.commissionPercentage||CONFIG.affiliateCommissionMin}% Commission</p><p style="color:#666;margin:8px 0;">Install to start promoting?</p><div style="display:flex;gap:10px;margin-top:12px;"><button class="btn-gold" onclick="closeModal();installProduct('${productId}')" style="flex:1;">✅ Install</button><button class="btn-outline" onclick="closeModal()" style="flex:1;">Cancel</button></div></div>`);}
async function installProduct(productId){const c=document.getElementById('affiliate-install-content');if(!c)return;c.innerHTML=`<div style="text-align:center;padding:40px;"><img src="app-icon.png" width="100" style="border-radius:20px;animation:pulse 1.5s infinite;"><h3 style="margin:20px 0;">Installing Product...</h3><div style="width:100%;height:6px;background:#eee;border-radius:3px;"><div id="inst-fill" style="height:100%;background:#FFD700;width:0%;transition:width 0.3s;"></div></div><p id="inst-status">Preparing...</p></div>`;const stages=[{p:20,t:'Checking...'},{p:40,t:'Generating link...'},{p:60,t:'Setting up...'},{p:80,t:'Installing...'},{p:100,t:'Complete!'}];let i=0;const timer=setInterval(()=>{if(i>=stages.length){clearInterval(timer);finishInstall(productId,c);return;}const s=stages[i];const fill=document.getElementById('inst-fill'),status=document.getElementById('inst-status');if(fill)fill.style.width=s.p+'%';if(status)status.textContent=s.t;i++;},1000);}
async function finishInstall(productId,c){const pDoc=await db.collection('products').doc(productId).get();const p=pDoc.data();if(!p){c.innerHTML='<p style="text-align:center;color:red;">Error</p>';return;}const link=CONFIG.baseUrl+'/r/'+APP.user.uid+'/'+productId;const exist=await db.collection('affiliate_products').where('affiliateId','==',APP.user.uid).where('productId','==',productId).where('status','==','active').get();if(!exist.empty){c.innerHTML=`<div style="text-align:center;padding:40px;"><i class="fas fa-check-circle" style="font-size:60px;color:#FFD700;"></i><h3>Already Installed!</h3><div style="background:#f5f5f5;padding:16px;border-radius:12px;margin:16px 0;word-break:break-all;"><p style="color:#33B5E5;">${link}</p><button class="btn-small-gold" onclick="copyText('${link}')">Copy Link</button></div><button class="btn-gold" onclick="goTo('affiliate')">Dashboard</button></div>`;return;}await db.collection('affiliate_products').add({affiliateId:APP.user.uid,productId,productName:p.name,productImage:p.images?.[0]||'',productPrice:p.price,commissionPercentage:p.commissionPercentage||CONFIG.affiliateCommissionMin,affiliateLink:link,status:'active',clicks:0,conversions:0,totalCommission:0,installedAt:firebase.firestore.FieldValue.serverTimestamp()});await db.collection('products').doc(productId).update({totalAffiliates:firebase.firestore.FieldValue.increment(1)});c.innerHTML=`<div style="text-align:center;padding:40px;"><i class="fas fa-check-circle" style="font-size:60px;color:#00C851;"></i><h3>Installed!</h3><div style="background:#f5f5f5;padding:16px;border-radius:12px;margin:16px 0;word-break:break-all;"><p style="font-size:12px;color:#999;">Your Link:</p><p style="color:#33B5E5;">${link}</p><button class="btn-small-gold" onclick="copyText('${link}')">Copy Link</button></div><button class="btn-gold" onclick="goTo('affiliate')">Dashboard</button></div>`;}

// ============ MERCHANT ============
async function loadMerchantDashboard(){if(!APP.authenticated)return;await refreshProfile();const c=document.getElementById('merchant-content');if(!c)return;if(!APP.profile?.isMerchant){c.innerHTML=`<div style="text-align:center;padding:40px;"><div class="subscription-banner"><i class="fas fa-store" style="font-size:48px;display:block;margin-bottom:12px;"></i><h3>Become a Merchant</h3><p>Sell globally. Lifetime access.</p><p style="font-size:20px;font-weight:700;">$${CONFIG.merchantPrice} Forever</p><button class="btn-gold" onclick="selectAccountType('merchant')" style="width:100%;">Subscribe Now</button></div></div>`;return;}if(!APP.profile?.storeActive){c.innerHTML=`<div style="text-align:center;padding:40px;"><i class="fas fa-store" style="font-size:48px;color:#FFD700;display:block;margin-bottom:12px;"></i><h3>Set Up Store</h3><button class="btn-gold mt-20" onclick="goTo('store-setup')">Set Up</button></div>`;return;}const isVer=APP.profile?.isVerifiedMerchant||false;const pSnap=await db.collection('products').where('merchantId','==',APP.user.uid).get();const products=pSnap.docs.map(d=>({id:d.id,...d.data()}));const oSnap=await db.collection('orders').where('merchantId','==',APP.user.uid).orderBy('createdAt','desc').limit(20).get();const orders=oSnap.docs.map(d=>({id:d.id,...d.data()}));const rev=orders.reduce((s,o)=>s+(o.total||0),0);const pending=orders.filter(o=>['processing','shipped'].includes(o.status));const active=products.filter(p=>p.status==='active');c.innerHTML=`${isVer?`<div style="display:flex;align-items:center;gap:8px;justify-content:center;margin-bottom:16px;"><span style="background:#0095F6;color:#fff;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;">✓</span><span style="color:#0095F6;font-weight:600;">Verified Merchant</span></div>`:''}<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:16px;"><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FFD700;">${active.length}</p><p style="font-size:12px;">Active</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#00C851;">${fmt(rev)}</p><p style="font-size:12px;">Revenue</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FFBB33;">${pending.length}</p><p style="font-size:12px;">Pending</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#33B5E5;">${orders.length}</p><p style="font-size:12px;">Orders</p></div></div><div style="display:flex;gap:10px;margin-bottom:16px;"><button class="btn-gold" onclick="goTo('add-product')" style="flex:1;">+ Add Product</button><button class="btn-gold" onclick="goTo('store-setup')" style="flex:1;">Edit Store</button></div>${APP.profile?.totalSales>=100?`<div style="background:#FFFDE7;padding:12px;border-radius:12px;margin-bottom:16px;text-align:center;"><p>⭐ Eligible for Sponsorship!</p><button class="btn-small-gold mt-10" onclick="sponsorProduct()">Sponsor ($${CONFIG.sponsorshipFee}/mo)</button></div>`:''}<h3>My Products</h3>${products.map(p=>`<div style="display:flex;gap:10px;background:#fff;padding:10px;border-radius:10px;margin-bottom:8px;align-items:center;"><img src="${p.images?.[0]||'app-icon.png'}" style="width:50px;height:50px;border-radius:8px;"><div style="flex:1;"><p style="font-weight:600;">${p.name}</p><p style="font-size:12px;color:#FFD700;">${fmt(p.price)}</p></div><button class="btn-small-gold" onclick="toggleProduct('${p.id}','${p.status}')">${p.status==='active'?'Disable':'Enable'}</button></div>`).join('')||'<p style="text-align:center;color:#999;">No products</p>'}<h3 style="margin-top:16px;">Recent Orders</h3>${orders.slice(0,10).map(o=>`<div style="background:#fff;padding:12px;border-radius:10px;margin-bottom:8px;"><div style="display:flex;justify-content:space-between;"><p style="font-weight:600;">#${o.id.slice(-8)}</p><span style="font-size:10px;padding:2px 8px;border-radius:8px;background:#FFF3E0;">${o.status}</span></div><p style="font-size:12px;">${o.items?.[0]?.name||'Product'} x${o.items?.[0]?.quantity||1}</p><p style="font-weight:600;color:#FFD700;">${fmt(o.total)}</p>${['processing'].includes(o.status)?`<button class="btn-small-gold mt-10" onclick="markShipped('${o.id}')">Mark Shipped</button>`:''}</div>`).join('')||'<p style="text-align:center;color:#999;">No orders</p>'}`;}
async function toggleProduct(id,status){await db.collection('products').doc(id).update({status:status==='active'?'disabled':'active'});toast('Updated','success');loadMerchantDashboard();}
async function markShipped(orderId){await db.collection('orders').doc(orderId).update({status:'shipped',updatedAt:firebase.firestore.FieldValue.serverTimestamp()});const o=await db.collection('orders').doc(orderId).get();await addNotification(o.data().userId,'Order Shipped','Order #'+orderId.slice(-8)+' shipped!','📦');toast('Marked shipped','success');loadMerchantDashboard();}
async function sponsorProduct(){const snap=await db.collection('products').where('merchantId','==',APP.user.uid).where('status','==','active').get();const products=snap.docs.map(d=>({id:d.id,...d.data()}));if(!products.length){toast('No active products','error');return;}openModal(`<h3>⭐ Sponsor Product</h3><p style="color:#666;">$${CONFIG.sponsorshipFee}/month</p><div class="form-group"><select id="sponsor-pid">${products.map(p=>`<option value="${p.id}">${p.name} - ${fmt(p.price)}</option>`).join('')}</select></div><button class="btn-gold mt-10" onclick="confirmSponsor()" style="width:100%;">Pay & Sponsor</button><button class="btn-outline mt-10" onclick="closeModal()" style="width:100%;">Cancel</button>`);}
async function confirmSponsor(){const pid=document.getElementById('sponsor-pid')?.value;if(!pid)return;closeModal();FlutterwaveCheckout({public_key:CONFIG.flutterwaveKey,tx_ref:'spn_'+Date.now(),amount:CONFIG.sponsorshipFee,currency:'USD',customer:{email:APP.user.email},callback:async function(res){if(res.status==='successful'){await db.collection('products').doc(pid).update({sponsored:true,sponsoredUntil:Date.now()+2592000000});toast('✅ Sponsored!','success');loadMerchantDashboard();}},onclose:()=>toast('Cancelled','warning')});}
async function loadStoreSetup(){const c=document.getElementById('store-setup-content');if(!c)return;c.innerHTML=`<h3>🏪 Store Setup</h3><p style="color:#666;">Choose template</p><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:16px 0;">${STORE_TEMPLATES.map(t=>`<div onclick="selectTemplate('${t.id}',this)" style="border:2px solid ${APP.profile?.storeTemplate===t.id?'#FFD700':'#ddd'};border-radius:12px;overflow:hidden;cursor:pointer;text-align:center;"><div style="background:${t.color};padding:40px;font-size:48px;">${t.icon}</div><p style="padding:8px;font-weight:600;">${t.name}</p></div>`).join('')}</div><div class="form-group"><label>Store Name</label><input type="text" id="store-name" value="${APP.profile?.storeName||'My Store'}"></div><button class="btn-gold mt-10" onclick="saveStore()" style="width:100%;">${APP.profile?.storeActive?'Update':'Launch'} Store</button>`;}
let selectedTemplate=null;
function selectTemplate(id,el){document.querySelectorAll('[onclick*="selectTemplate"]').forEach(c=>{c.style.border='2px solid #ddd';});el.style.border='2px solid #FFD700';selectedTemplate=id;}
async function saveStore(){const t=selectedTemplate||APP.profile?.storeTemplate;if(!t){toast('Select template','warning');return;}const n=document.getElementById('store-name')?.value?.trim()||'My Store';await db.collection('users').doc(APP.user.uid).update({storeTemplate:t,storeName:n,storeActive:true});toast('✅ Store launched!','success');goTo('merchant');}
async function loadAddProduct(){const c=document.getElementById('add-product-content');if(!c)return;c.innerHTML=`<h3>Add Product</h3><div class="form-group"><label>Name *</label><input type="text" id="ap-name"></div><div class="form-group"><label>Price (USD) *</label><input type="number" id="ap-price" step="0.01"></div><div class="form-group"><label>Category *</label><select id="ap-cat"><option value="">Select</option>${CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="form-group"><label>Stock *</label><input type="number" id="ap-stock"></div><div class="form-group"><label>Commission (%)</label><input type="number" id="ap-comm" value="4" step="0.1"></div><div class="form-group"><label>Colors (comma)</label><input type="text" id="ap-colors" placeholder="Black,White,Red"></div><div class="form-group"><label>Sizes (comma)</label><input type="text" id="ap-sizes" placeholder="S,M,L,XL"></div><div class="form-group"><label>Description</label><textarea id="ap-desc" rows="3"></textarea></div><div class="form-group"><label>Images (up to 5)</label><input type="file" id="ap-images" accept="image/*" multiple onchange="previewImgs()"><div id="img-preview" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px;"></div></div><div class="form-group"><label>Video URL (optional)</label><input type="text" id="ap-video" placeholder="https://..."></div><button class="btn-gold mt-10" onclick="submitProduct()" style="width:100%;">Publish</button>`;}
function previewImgs(){const files=document.getElementById('ap-images')?.files;const p=document.getElementById('img-preview');if(!p)return;p.innerHTML='';Array.from(files||[]).slice(0,5).forEach(f=>{const r=new FileReader();r.onload=e=>{p.innerHTML+=`<img src="${e.target.result}" style="width:80px;height:80px;object-fit:cover;border-radius:8px;">`;};r.readAsDataURL(f);});}
async function submitProduct(){const name=document.getElementById('ap-name')?.value?.trim();const price=parseFloat(document.getElementById('ap-price')?.value);const cat=document.getElementById('ap-cat')?.value;const stock=parseInt(document.getElementById('ap-stock')?.value);if(!name||!price||!cat||!stock){toast('Fill required fields','error');return;}const comm=parseFloat(document.getElementById('ap-comm')?.value)||4;const colors=document.getElementById('ap-colors')?.value?.split(',').map(s=>s.trim()).filter(Boolean)||[];const sizes=document.getElementById('ap-sizes')?.value?.split(',').map(s=>s.trim()).filter(Boolean)||[];const desc=document.getElementById('ap-desc')?.value?.trim()||'';const vid=document.getElementById('ap-video')?.value?.trim()||'';const imgFiles=document.getElementById('ap-images')?.files||[];const imgUrls=[];for(let i=0;i<Math.min(imgFiles.length,5);i++){const fd=new FormData();fd.append('file',imgFiles[i]);fd.append('upload_preset',CONFIG.cloudinaryPreset);try{const r=await fetch(CONFIG.cloudinaryUrl,{method:'POST',body:fd});const d=await r.json();if(d.secure_url)imgUrls.push(d.secure_url);}catch(e){}}await db.collection('products').add({name,price,category:cat,stock,commissionPercentage:comm,colors,sizes,description:desc,images:imgUrls,videoUrl:vid,merchantId:APP.user.uid,merchantName:APP.profile?.displayName||'Unknown',merchantVerified:APP.profile?.isVerifiedMerchant||false,merchantFlagged:APP.profile?.isFlagged||false,flaggedUntil:APP.profile?.flaggedUntil||null,status:'active',sponsored:false,totalSales:0,avgRating:0,reviewCount:0,totalAffiliates:0,createdAt:firebase.firestore.FieldValue.serverTimestamp()});toast('✅ Product published!','success');goTo('merchant');}

// ============ WALLET ============
async function loadWallet(){if(!APP.authenticated)return;await refreshProfile();const c=document.getElementById('wallet-content');if(!c)return;c.innerHTML=`<div style="text-align:center;margin-bottom:16px;"><span style="font-size:40px;">${APP.country.flag}</span><p style="font-size:12px;color:#666;">${APP.country.name} · ${APP.country.currency} · 1 USD = ${APP.exchangeRate} ${APP.country.currency}</p></div><div class="wallet-full-card"><div style="text-align:center;margin-bottom:20px;"><p style="color:rgba(255,255,255,0.7);font-size:12px;">Available Balance</p><h1 style="font-size:42px;font-weight:800;color:#FFD700;">${fmt(APP.profile?.walletBalance||0)}</h1><p style="color:rgba(255,255,255,0.5);">≈ ${((APP.profile?.walletBalance||0)*APP.exchangeRate).toFixed(2)} ${APP.country.currency}</p></div><div class="wallet-balance-row"><span>Pending</span><span>${fmt(APP.profile?.pendingBalance||0)}</span></div><div class="wallet-balance-row"><span>Escrow</span><span>${fmt(APP.profile?.escrowBalance||0)}</span></div><div class="wallet-balance-row"><span>Affiliate Earnings</span><span>${fmt(APP.profile?.affiliateEarnings||0)}</span></div><div class="wallet-balance-row"><span>Withdrawn</span><span>${fmt(APP.profile?.withdrawnBalance||0)}</span></div></div><div style="display:flex;gap:10px;margin-bottom:20px;"><button class="btn-gold" onclick="showDeposit()" style="flex:1;">Deposit</button><button class="btn-gold" onclick="showWithdraw()" style="flex:1;">Withdraw</button></div><div class="section"><div class="section-header"><h3>Bank Accounts</h3><button class="btn-text" onclick="showAddBank()">+ Add</button></div><div id="bank-list">${renderBanks(APP.profile?.bankAccounts||[])}</div></div><div class="section"><h3>Recent Transactions</h3><div id="recent-tx"><p style="text-align:center;color:#999;">Loading...</p></div></div>`;loadRecentTransactions();}
function renderBanks(accounts){if(!accounts.length)return'<p style="text-align:center;color:#999;padding:20px;">No bank accounts</p>';return accounts.map(a=>`<div class="bank-account-card"><div><p style="font-weight:600;">${a.bankName}</p><p style="font-size:12px;color:#666;">${a.accountName} · ****${a.accountNumber.slice(-4)}</p>${a.isPrimary?'<span style="background:#E8F5E9;color:#2E7D32;padding:2px 8px;border-radius:10px;font-size:10px;">PRIMARY</span>':''}</div><div>${!a.isPrimary&&!a.disabled?`<button class="btn-small-gold" onclick="setPrimaryBank('${a.id}')">Set Primary</button>`:''}${!a.disabled?`<button onclick="disableBank('${a.id}')" style="background:none;border:none;color:#FF4444;cursor:pointer;"><i class="fas fa-ban"></i></button>`:''}</div></div>`).join('');}
function showDeposit(){openModal(`<h3>Deposit ${APP.country.flag}</h3><p style="color:#666;text-align:center;">Min: $${CONFIG.minDeposit} | Max: $${CONFIG.maxDeposit}</p><p style="text-align:center;font-size:13px;">1 USD = ${APP.exchangeRate} ${APP.country.currency}</p><div class="form-group"><label>Amount (${APP.country.currency})</label><input type="number" id="dep-local" oninput="updateDepUSD()" style="font-size:20px;font-weight:700;text-align:center;"></div><div class="form-group"><label>Amount (USD)</label><input type="text" id="dep-usd" readonly style="text-align:center;background:#f5f5f5;"></div><button class="btn-gold mt-10" onclick="processDeposit()" style="width:100%;">Pay</button><button class="btn-outline mt-10" onclick="closeModal()" style="width:100%;">Cancel</button>`);}
function updateDepUSD(){const local=parseFloat(document.getElementById('dep-local')?.value)||0;const usd=(local/APP.exchangeRate).toFixed(2);const el=document.getElementById('dep-usd');if(el)el.value=usd;}
function processDeposit(){const usd=parseFloat(document.getElementById('dep-usd')?.value);const local=parseFloat(document.getElementById('dep-local')?.value);if(!usd||usd<CONFIG.minDeposit){toast('Min $'+CONFIG.minDeposit,'error');return;}closeModal();FlutterwaveCheckout({public_key:CONFIG.flutterwaveKey,tx_ref:'dep_'+Date.now(),amount:local,currency:APP.country.currency,customer:{email:APP.user.email},callback:async function(res){if(res.status==='successful'){await db.collection('users').doc(APP.user.uid).update({walletBalance:firebase.firestore.FieldValue.increment(usd)});await db.collection('transactions').add({userId:APP.user.uid,type:'deposit',amount:usd,localAmount:local,currency:APP.country.currency,status:'completed',createdAt:firebase.firestore.FieldValue.serverTimestamp()});await addNotification(APP.user.uid,'Deposit','$'+usd.toFixed(2)+' credited','💰');toast('✅ Deposited!','success');loadWallet();}},onclose:()=>toast('Cancelled','warning')});}
function showWithdraw(){const accounts=(APP.profile?.bankAccounts||[]).filter(a=>!a.disabled);const primary=accounts.find(a=>a.isPrimary)||accounts[0];if(!primary){toast('Add bank first','warning');showAddBank();return;}openModal(`<h3>Withdraw ${APP.country.flag}</h3><p style="color:#666;">Available: ${fmt(APP.profile?.walletBalance||0)}</p><div class="form-group"><label>Amount (USD)</label><input type="number" id="wd-usd" oninput="updateWdLocal()" style="font-size:20px;font-weight:700;text-align:center;"></div><div class="form-group"><label>Receive (${APP.country.currency})</label><input type="text" id="wd-local" readonly style="text-align:center;background:#f5f5f5;"></div><div class="form-group"><label>Account</label><select id="wd-bank">${accounts.map(a=>`<option value="${a.id}" ${a.isPrimary?'selected':''}>${a.bankName} - ****${a.accountNumber.slice(-4)}</option>`).join('')}</select></div><button class="btn-gold mt-10" onclick="processWithdraw()" style="width:100%;">Withdraw</button><button class="btn-outline mt-10" onclick="closeModal()" style="width:100%;">Cancel</button>`);}
function updateWdLocal(){const usd=parseFloat(document.getElementById('wd-usd')?.value)||0;const local=(usd*APP.exchangeRate).toFixed(2);const el=document.getElementById('wd-local');if(el)el.value=local;}
async function processWithdraw(){const usd=parseFloat(document.getElementById('wd-usd')?.value);const local=parseFloat(document.getElementById('wd-local')?.value);const bankId=document.getElementById('wd-bank')?.value;if(!usd||usd<CONFIG.minWithdraw){toast('Min $'+CONFIG.minWithdraw,'error');return;}if(usd>(APP.profile?.walletBalance||0)){toast('Insufficient','error');return;}closeModal();const bank=APP.profile.bankAccounts.find(a=>a.id===bankId);await db.collection('users').doc(APP.user.uid).update({walletBalance:firebase.firestore.FieldValue.increment(-usd),withdrawnBalance:firebase.firestore.FieldValue.increment(usd)});await db.collection('withdrawals').add({userId:APP.user.uid,amount:usd,localAmount:local,currency:APP.country.currency,bankAccount:bank,status:'pending',createdAt:firebase.firestore.FieldValue.serverTimestamp()});await addNotification(APP.user.uid,'Withdrawal','$'+usd.toFixed(2)+' submitted','💸');toast('✅ Submitted!','success');loadWallet();}
function showAddBank(){const banks=typeof getBanksForCountry==='function'?getBanksForCountry(APP.country.code):[{name:'Bank',code:'BK'}];openModal(`<h3>Add Bank ${APP.country.flag}</h3><div class="form-group"><label>Bank</label><select id="bank-name">${banks.map(b=>`<option>${b.name}</option>`).join('')}<option value="other">Other</option></select></div><div class="form-group" id="other-bank" style="display:none;"><input type="text" id="bank-other" placeholder="Bank name"></div><div class="form-group"><label>Account Name</label><input type="text" id="acct-name"></div><div class="form-group"><label>Account Number</label><input type="text" id="acct-num"></div><button class="btn-gold mt-10" onclick="addBank()" style="width:100%;">Save</button><button class="btn-outline mt-10" onclick="closeModal()" style="width:100%;">Cancel</button>`);setTimeout(()=>{const sel=document.getElementById('bank-name'),other=document.getElementById('other-bank');if(sel&&other)sel.onchange=function(){other.style.display=this.value==='other'?'block':'none';};},200);}
async function addBank(){const sel=document.getElementById('bank-name');const name=sel?.value==='other'?document.getElementById('bank-other')?.value?.trim():sel?.value;const acctName=document.getElementById('acct-name')?.value?.trim();const acctNum=document.getElementById('acct-num')?.value?.trim();if(!name||!acctName||!acctNum){toast('Fill all','error');return;}const accounts=[...(APP.profile?.bankAccounts||[])];const isPrimary=accounts.length===0;if(isPrimary)accounts.forEach(a=>a.isPrimary=false);accounts.push({id:'bank_'+Date.now(),bankName:name,accountName:acctName,accountNumber:acctNum,isPrimary,disabled:false});await db.collection('users').doc(APP.user.uid).update({bankAccounts:accounts});closeModal();toast('✅ Added!','success');loadWallet();}
async function setPrimaryBank(id){const accounts=APP.profile.bankAccounts.map(a=>({...a,isPrimary:a.id===id}));await db.collection('users').doc(APP.user.uid).update({bankAccounts:accounts});toast('Updated','success');loadWallet();}
async function disableBank(id){if(!confirm('Disable?'))return;const accounts=APP.profile.bankAccounts.map(a=>a.id===id?{...a,disabled:true,isPrimary:false}:a);const active=accounts.filter(a=>!a.disabled);if(active.length&&!active.find(a=>a.isPrimary))active[0].isPrimary=true;await db.collection('users').doc(APP.user.uid).update({bankAccounts:accounts});toast('Disabled','success');loadWallet();}
async function loadRecentTransactions(){const c=document.getElementById('recent-tx');if(!c)return;try{const snap=await db.collection('transactions').where('userId','==',APP.user.uid).orderBy('createdAt','desc').limit(10).get();if(snap.empty){c.innerHTML='<p style="text-align:center;color:#999;">No transactions</p>';return;}c.innerHTML=snap.docs.map(doc=>{const tx=doc.data();const isIn=tx.type==='deposit'||tx.type==='affiliate_earning';return`<div style="display:flex;justify-content:space-between;padding:12px;border-bottom:1px solid #f5f5f5;"><div><p style="font-weight:600;">${tx.type.replace(/_/g,' ')}</p><p style="font-size:11px;color:#999;">${timeAgo(tx.createdAt)}</p></div><p style="font-weight:700;color:${isIn?'#00C851':'#FF4444'};">${isIn?'+':'-'}${fmt(tx.amount)}</p></div>`;}).join('');}catch(e){}}
async function loadTransactions(){if(!APP.authenticated)return;const screen=document.getElementById('screen-transactions');if(!screen)return;let mc=screen.querySelector('.main-content');if(!mc){mc=document.createElement('div');mc.className='main-content';screen.appendChild(mc);}mc.innerHTML='<h3>Transactions</h3><div id="all-tx"><p style="text-align:center;color:#999;">Loading...</p></div>';try{const snap=await db.collection('transactions').where('userId','==',APP.user.uid).orderBy('createdAt','desc').limit(50).get();const c=document.getElementById('all-tx');if(snap.empty){c.innerHTML='<p style="text-align:center;color:#999;">No transactions</p>';return;}c.innerHTML=snap.docs.map(doc=>{const tx=doc.data();const isIn=tx.type==='deposit'||tx.type==='affiliate_earning';return`<div style="display:flex;justify-content:space-between;padding:14px;border-bottom:1px solid #f0f0f0;"><div><p style="font-weight:600;">${tx.type.replace(/_/g,' ')}</p><p style="font-size:12px;color:#999;">${timeAgo(tx.createdAt)}</p></div><p style="font-weight:700;color:${isIn?'#00C851':'#FF4444'};">${isIn?'+':'-'}${fmt(tx.amount)}</p></div>`;}).join('');}catch(e){}}

// ============ CHECKOUT ============
function loadCheckout(){if(!APP.authenticated)return;const c=document.getElementById('checkout-content');if(!c)return;if(!APP.cart.length){c.innerHTML='<div style="text-align:center;padding:60px;"><i class="fas fa-shopping-cart" style="font-size:60px;color:#ddd;"></i><h3>Cart Empty</h3><button class="btn-gold mt-20" onclick="goTo(\'marketplace\')">Shop</button></div>';return;}const total=APP.cart.reduce((s,i)=>s+i.total,0);c.innerHTML=`<h3>Checkout</h3><div style="margin:16px 0;"><h4>📦 Shipping</h4><div class="form-group"><label>Name *</label><input type="text" id="s-name" value="${APP.profile?.displayName||''}"></div><div class="form-group"><label>Country *</label><select id="s-country">${typeof COUNTRIES!=='undefined'?COUNTRIES.map(ct=>`<option value="${ct.code}" ${ct.code===APP.country.code?'selected':''}>${ct.flag} ${ct.name}</option>`).join(''):''}</select></div><div class="form-group"><label>State *</label><input type="text" id="s-state"></div><div class="form-group"><label>City *</label><input type="text" id="s-city"></div><div class="form-group"><label>Address *</label><input type="text" id="s-address"></div><div class="form-group"><label>Postal Code *</label><input type="text" id="s-postal"></div><div class="form-group"><label>Phone *</label><input type="tel" id="s-phone"></div></div><div style="background:#f9f9f9;border-radius:12px;padding:16px;">${APP.cart.map((item,i)=>`<div style="display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #eee;"><img src="${item.image||'app-icon.png'}" style="width:50px;height:50px;border-radius:8px;"><div style="flex:1;"><p style="font-weight:600;">${item.name}</p><p style="font-size:11px;color:#999;">${item.color||''} ${item.size||''} ×${item.quantity}</p></div><p style="font-weight:700;color:#FFD700;">${fmt(item.total)}</p><button onclick="removeCartItem(${i})" style="background:none;border:none;color:#FF4444;">×</button></div>`).join('')}<div style="display:flex;justify-content:space-between;padding:12px 0;font-weight:700;border-top:2px solid #FFD700;"><span>Total</span><span style="color:#FFD700;">${fmt(total)}</span></div></div><p>Balance: ${fmt(APP.profile?.walletBalance||0)}</p><button class="btn-gold" onclick="processCheckout()" style="width:100%;" ${total>(APP.profile?.walletBalance||0)?'disabled':''}>${total>(APP.profile?.walletBalance||0)?'Insufficient':'Pay '+fmt(total)}</button><p style="font-size:11px;color:#999;text-align:center;margin-top:8px;">🔒 Escrow protected</p>`;}
function removeCartItem(i){APP.cart.splice(i,1);localStorage.setItem('shoplify_cart',JSON.stringify(APP.cart));loadCheckout();}
async function processCheckout(){const name=document.getElementById('s-name')?.value?.trim();const country=document.getElementById('s-country')?.value;const state=document.getElementById('s-state')?.value?.trim();const city=document.getElementById('s-city')?.value?.trim();const address=document.getElementById('s-address')?.value?.trim();const postal=document.getElementById('s-postal')?.value?.trim();const phone=document.getElementById('s-phone')?.value?.trim();if(!name||!country||!state||!city||!address||!postal||!phone){toast('Fill all fields','error');return;}const total=APP.cart.reduce((s,i)=>s+i.total,0);await refreshProfile();if(total>(APP.profile?.walletBalance||0)){toast('Insufficient','error');return;}try{const ordersByMerchant={};for(const item of APP.cart){const pDoc=await db.collection('products').doc(item.productId).get();const p=pDoc.data();if(!p)continue;const mid=p.merchantId||'unknown';if(!ordersByMerchant[mid])ordersByMerchant[mid]={merchantId:mid,items:[],total:0};ordersByMerchant[mid].items.push(item);ordersByMerchant[mid].total+=item.total;}for(const[mid,od]of Object.entries(ordersByMerchant)){const orderId=genId('ord');await db.collection('orders').doc(orderId).set({userId:APP.user.uid,merchantId:mid,items:od.items,total:od.total,escrowAmount:od.total,status:'processing',shipping:{name,country,state,city,address,postal,phone},createdAt:firebase.firestore.FieldValue.serverTimestamp()});for(const item of od.items){await db.collection('products').doc(item.productId).update({stock:firebase.firestore.FieldValue.increment(-item.quantity),totalSales:firebase.firestore.FieldValue.increment(item.quantity)});}await addNotification(mid,'New Order!','New order: '+fmt(od.total),'📦');}await db.collection('users').doc(APP.user.uid).update({walletBalance:firebase.firestore.FieldValue.increment(-total),escrowBalance:firebase.firestore.FieldValue.increment(total)});APP.cart=[];localStorage.removeItem('shoplify_cart');toast('✅ Order placed!','success');goTo('orders');}catch(e){toast('Error','error');}}

// ============ ORDERS ============
async function loadOrders(){if(!APP.authenticated)return;const c=document.getElementById('orders-content');if(!c)return;c.innerHTML='<p style="text-align:center;color:#999;">Loading...</p>';try{const snap=await db.collection('orders').where('userId','==',APP.user.uid).orderBy('createdAt','desc').limit(30).get();if(snap.empty){c.innerHTML='<p style="text-align:center;padding:60px;color:#999;">No orders</p>';return;}c.innerHTML=snap.docs.map(doc=>renderOrderCard(doc.id,doc.data())).join('');}catch(e){c.innerHTML='<p style="text-align:center;color:#999;">Error</p>';}}
function renderOrderCard(orderId,order){const si=getStatusInfo(order.status);const items=order.items||[];return`<div style="background:#fff;border-radius:12px;padding:16px;margin-bottom:12px;"><div style="display:flex;justify-content:space-between;margin-bottom:12px;"><div><p style="font-size:11px;color:#999;">#${orderId.slice(-10)}</p><p style="font-size:12px;">${timeAgo(order.createdAt)}</p></div><span style="background:${si.bg};color:${si.color};padding:4px 12px;border-radius:12px;font-size:11px;">${si.icon} ${si.label}</span></div>${items.map(item=>`<div style="display:flex;gap:10px;padding:8px 0;border-top:1px solid #f5f5f5;"><img src="${item.image||'app-icon.png'}" style="width:50px;height:50px;border-radius:8px;"><div style="flex:1;"><p style="font-weight:600;">${item.name}</p><p style="font-size:11px;color:#999;">${item.color||''} ${item.size||''} ×${item.quantity}</p></div><p style="font-weight:700;color:#FFD700;">${fmt(item.total)}</p></div>`).join('')}${order.trackingNumber?`<p style="font-size:12px;color:#33B5E5;">📮 ${order.trackingNumber}</p>`:''}<div style="display:flex;justify-content:space-between;padding:8px 0;border-top:2px solid #FFD700;"><span>Total</span><span style="font-weight:700;color:#FFD700;">${fmt(order.total)}</span></div><div style="display:flex;gap:8px;margin-top:12px;">${order.status==='delivered'?`<button class="btn-gold" onclick="confirmDelivery('${orderId}')" style="flex:1;">✅ Confirm</button>`:''}${['processing','shipped','delivered'].includes(order.status)?`<button class="btn-outline" style="flex:1;color:#FF4444;border-color:#FF4444;" onclick="openDispute('${orderId}')">🚨 Report</button>`:''}</div></div>`;}
function getStatusInfo(s){const st={processing:{bg:'#FFF3E0',color:'#E65100',icon:'⏳',label:'Processing'},shipped:{bg:'#E3F2FD',color:'#1565C0',icon:'📦',label:'Shipped'},delivered:{bg:'#E8F5E9',color:'#2E7D32',icon:'📬',label:'Delivered'},completed:{bg:'#E8F5E9',color:'#1B5E20',icon:'✅',label:'Completed'},disputed:{bg:'#FFEBEE',color:'#C62828',icon:'🚨',label:'Disputed'}};return st[s]||{bg:'#F5F5F5',color:'#999',icon:'📋',label:s};}
async function confirmDelivery(orderId){if(!confirm('Confirm delivery?'))return;const order=await db.collection('orders').doc(orderId).get();const o=order.data();await db.collection('orders').doc(orderId).update({status:'completed',deliveryConfirmed:true});await db.collection('users').doc(o.merchantId).update({walletBalance:firebase.firestore.FieldValue.increment(o.escrowAmount)});await db.collection('users').doc(APP.user.uid).update({escrowBalance:firebase.firestore.FieldValue.increment(-o.escrowAmount)});if(o.items){for(const item of o.items){const affSnap=await db.collection('affiliate_products').where('productId','==',item.productId).where('status','==','active').limit(1).get();if(!affSnap.empty){const ad=affSnap.docs[0].data();const comm=calcCommission(item.total,ad.commissionPercentage);await db.collection('affiliate_products').doc(affSnap.docs[0].id).update({totalCommission:firebase.firestore.FieldValue.increment(comm)});const aff=await db.collection('users').doc(ad.affiliateId).get();if(aff.exists){await db.collection('users').doc(ad.affiliateId).update({pendingEarnings:firebase.firestore.FieldValue.increment(-comm),affiliateEarnings:firebase.firestore.FieldValue.increment(comm),walletBalance:firebase.firestore.FieldValue.increment(comm)});await addNotification(ad.affiliateId,'Commission!','Earned '+fmt(comm),'💰');}}}}toast('✅ Confirmed!','success');loadOrders();}
function openDispute(orderId){openModal(`<h3>🚨 Report</h3><div class="form-group"><label>Issue</label><select id="disp-type"><option>Not Received</option><option>Damaged</option><option>Wrong Item</option><option>Other</option></select></div><div class="form-group"><label>Description</label><textarea id="disp-desc" rows="3"></textarea></div><button class="btn-gold mt-10" onclick="submitDispute('${orderId}')" style="width:100%;">Submit</button><button class="btn-outline mt-10" onclick="closeModal()" style="width:100%;">Cancel</button>`);}
async function submitDispute(orderId){const type=document.getElementById('disp-type')?.value;const desc=document.getElementById('disp-desc')?.value?.trim();if(!desc){toast('Describe issue','error');return;}closeModal();await db.collection('disputes').add({orderId,userId:APP.user.uid,type,description:desc,status:'open',createdAt:firebase.firestore.FieldValue.serverTimestamp()});await db.collection('orders').doc(orderId).update({disputed:true,status:'disputed'});toast('✅ Filed','success');loadOrders();}

// ============ PROFILE ============
async function loadProfile(){if(!APP.authenticated)return;await refreshProfile();const c=document.getElementById('profile-content');if(!c)return;const p=APP.profile||{};const isAmb=p.isAmbassador||false;c.innerHTML=`<div style="background:linear-gradient(135deg,${isAmb?'#B87333,#8B4513':'#FFD700,#E6C200'});border-radius:16px;padding:24px;text-align:center;color:#fff;margin-bottom:20px;"><img src="${p.photoURL||APP.user?.photoURL||'app-icon.png'}" style="width:80px;height:80px;border-radius:50%;border:4px solid #fff;margin-bottom:12px;" onclick="uploadProfilePic()"><div style="display:flex;align-items:center;justify-content:center;gap:8px;"><h3 style="color:${isAmb?'#FFD700':'#fff'};">${p.displayName||p.username||'User'}</h3>${p.isVerifiedAffiliate?'<span style="background:#0095F6;color:#fff;width:20px;height:20px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:10px;">✓</span>':''}${p.isVerifiedMerchant?'<span style="background:#0095F6;color:#fff;width:20px;height:20px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:10px;">✓</span>':''}${isAmb?'👑':''}</div><p>${p.email} ${APP.country.flag}</p><p style="font-size:20px;">${fmt(p.walletBalance||0)}</p><span style="background:rgba(255,255,255,0.3);padding:4px 12px;border-radius:12px;font-size:11px;">${p.accountType||'customer'}</span></div><div style="background:#25D366;border-radius:16px;padding:24px;text-align:center;color:#fff;margin-bottom:16px;"><i class="fab fa-whatsapp" style="font-size:48px;"></i><h3>Join WhatsApp Community</h3><p style="font-size:13px;">Updates, campaigns & support</p><a href="${CONFIG.whatsappCommunity}" target="_blank" style="display:inline-block;background:#fff;color:#25D366;padding:12px 24px;border-radius:12px;text-decoration:none;font-weight:700;margin-top:8px;">Join Now</a></div><div style="background:#fff;border-radius:12px;overflow:hidden;"><div class="profile-menu-item" onclick="goTo('orders')"><i class="fas fa-box"></i> Orders</div><div class="profile-menu-item" onclick="goTo('wallet')"><i class="fas fa-wallet"></i> Wallet</div>${APP.accountType==='affiliate'||APP.accountType==='merchant'?`<div class="profile-menu-item" onclick="goTo('analytics')"><i class="fas fa-chart-bar"></i> Analytics</div><div class="profile-menu-item" onclick="goTo('leaderboard')"><i class="fas fa-trophy"></i> Leaderboard</div>`:''}<div class="profile-menu-item" onclick="goTo('affiliate')"><i class="fas fa-link"></i> Affiliate</div><div class="profile-menu-item" onclick="goTo('merchant')"><i class="fas fa-store"></i> Merchant</div><div class="profile-menu-item" onclick="goTo('settings')"><i class="fas fa-cog"></i> Settings</div><div class="profile-menu-item" style="color:#FF4444;" onclick="signOut()"><i class="fas fa-sign-out-alt"></i> Logout</div></div><p style="text-align:center;font-size:11px;color:#ccc;margin-top:20px;">Shoplify v${CONFIG.version} · Powered by Rev</p>`;}
async function uploadProfilePic(){const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=async function(e){const file=e.target.files[0];if(!file)return;const fd=new FormData();fd.append('file',file);fd.append('upload_preset',CONFIG.cloudinaryPreset);try{const r=await fetch(CONFIG.cloudinaryUrl,{method:'POST',body:fd});const d=await r.json();if(d.secure_url){await db.collection('users').doc(APP.user.uid).update({photoURL:d.secure_url});toast('Updated!','success');loadProfile();}}catch(e){toast('Error','error');}};input.click();}

// ============ SETTINGS ============
function loadSettings(){const c=document.getElementById('settings-content');if(!c)return;c.innerHTML=`<h3>⚙️ Settings</h3><div class="settings-item" onclick="changeUname()"><span>Username</span><span>${APP.profile?.username||''} <i class="fas fa-chevron-right"></i></span></div><div class="settings-item"><span>Theme</span><select onchange="changeTheme(this.value)"><option>Light</option><option>Dark</option></select></div><div class="settings-item"><span>Text Size</span><select onchange="changeTextSize(this.value)"><option>Small</option><option selected>Medium</option><option>Large</option></select></div><div class="settings-item"><span>Version</span><span>${CONFIG.version}</span></div><div class="settings-item" onclick="signOut()" style="color:#FF4444;">Sign Out</div>`;}
function changeUname(){openModal(`<h3>Change Username</h3><input type="text" id="new-uname" value="${APP.profile?.username||''}"><button class="btn-gold mt-10" onclick="saveUname()" style="width:100%;">Save</button>`);}
async function saveUname(){const n=document.getElementById('new-uname')?.value?.trim();if(!n||n.length<3){toast('Min 3 chars','error');return;}const exist=await db.collection('users').where('username','==',n).limit(1).get();if(!exist.empty&&exist.docs[0].id!==APP.user.uid){toast('Taken','error');return;}await db.collection('users').doc(APP.user.uid).update({username:n});closeModal();toast('Updated!','success');}
function changeTheme(t){document.body.style.background=t==='Dark'?'#1a1a1a':'#fff';}
function changeTextSize(s){const sizes={Small:'14px',Medium:'16px',Large:'18px'};document.documentElement.style.fontSize=sizes[s]||'16px';}

// ============ LEADERBOARD ============
async function loadLeaderboard(){if(!APP.authenticated)return;const screen=document.getElementById('screen-leaderboard');if(!screen)return;let mc=screen.querySelector('.main-content');if(!mc){mc=document.createElement('div');mc.className='main-content';screen.appendChild(mc);}mc.innerHTML='<p style="text-align:center;color:#999;">Loading...</p>';try{const snap=await db.collection('users').orderBy('totalSales','desc').limit(20).get();const topAff=snap.docs.filter(d=>d.data().isAffiliate).slice(0,10);const topMer=snap.docs.filter(d=>d.data().isMerchant).slice(0,10);mc.innerHTML=`<h3>🏆 Leaderboard</h3><h4>Top Affiliates</h4>${topAff.map((d,i)=>{const u=d.data();return`<div style="display:flex;align-items:center;gap:12px;padding:12px;background:#fff;border-radius:10px;margin-bottom:8px;"><span style="font-size:24px;font-weight:800;color:${i===0?'#FFD700':i===1?'#C0C0C0':i===2?'#CD7F32':'#999'};">#${i+1}</span><div style="flex:1;"><p style="font-weight:600;">${u.displayName||u.username} ${u.isVerifiedAffiliate?'✓':''} ${u.isAmbassador?'👑':''}</p><p style="font-size:12px;">Sales: ${u.totalSales||0}</p></div><p style="font-weight:700;color:#FFD700;">${fmt(u.affiliateEarnings||0)}</p></div>`;}).join('')||'<p style="color:#999;">No data</p>'}<h4>Top Merchants</h4>${topMer.map((d,i)=>{const u=d.data();return`<div style="display:flex;align-items:center;gap:12px;padding:12px;background:#fff;border-radius:10px;margin-bottom:8px;"><span style="font-size:24px;font-weight:800;color:${i===0?'#FFD700':i===1?'#C0C0C0':i===2?'#CD7F32':'#999'};">#${i+1}</span><div style="flex:1;"><p style="font-weight:600;">${u.displayName||u.username} ${u.isVerifiedMerchant?'✓':''}</p><p style="font-size:12px;">Revenue: ${fmt(u.totalRevenue||0)}</p></div></div>`;}).join('')||'<p style="color:#999;">No data</p>'}`;}catch(e){}}

// ============ ANALYTICS ============
async function loadAnalytics(){if(!APP.authenticated)return;const screen=document.getElementById('screen-analytics');if(!screen)return;let mc=screen.querySelector('.main-content');if(!mc){mc=document.createElement('div');mc.className='main-content';screen.appendChild(mc);}mc.innerHTML='<p style="text-align:center;color:#999;">Loading...</p>';try{const isAff=APP.accountType==='affiliate';const col=isAff?'affiliate_products':'products';const field=isAff?'affiliateId':'merchantId';const snap=await db.collection(col).where(field,'==',APP.user.uid).get();const data=snap.docs.map(d=>d.data());const clicks=data.reduce((s,d)=>s+(d.clicks||0),0);const conv=data.reduce((s,d)=>s+(d.conversions||0),0);const earn=data.reduce((s,d)=>s+(d.totalCommission||0),0);mc.innerHTML=`<h3>📊 Analytics</h3><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:16px;"><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FFD700;">${fmt(earn)}</p><p>${isAff?'Earnings':'Revenue'}</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#33B5E5;">${clicks}</p><p>Clicks</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#00C851;">${conv}</p><p>Conversions</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FFBB33;">${clicks?((conv/clicks)*100).toFixed(1):'0'}%</p><p>Rate</p></div></div>`;}catch(e){}}

// ============ CUSTOMER SERVICE ============
async function loadCustomerService(){if(!APP.authenticated||APP.accountType!=='customerservice'){toast('Access denied','error');goTo('home');return;}const screen=document.getElementById('screen-customerservice');if(!screen)return;let mc=screen.querySelector('.main-content');if(!mc){mc=document.createElement('div');mc.className='main-content';screen.appendChild(mc);}const snap=await db.collection('disputes').where('status','==','open').orderBy('createdAt','desc').get();const disputes=snap.docs.map(d=>({id:d.id,...d.data()}));mc.innerHTML=`<h3>🎧 Customer Service</h3><h4>Open Disputes (${disputes.length})</h4>${disputes.map(d=>`<div style="background:#fff;padding:14px;border-radius:10px;margin-bottom:10px;"><p style="font-weight:600;">#${d.orderId?.slice(-8)}</p><p style="color:#FF4444;">${d.type}</p><p>${d.description}</p><p style="font-size:11px;">${d.userEmail}</p><div style="display:flex;gap:8px;margin-top:8px;"><button class="btn-small-gold" onclick="resolveDisp('${d.id}','refund')">Refund</button><button class="btn-small-gold" onclick="resolveDisp('${d.id}','release')">Release</button><button class="btn-small-gold" style="background:#FF4444;" onclick="flagMerchantCS('${d.id}')">🚩 Flag</button><button class="btn-small-gold" style="background:#FF4444;" onclick="requestBanCS('${d.id}')">🔨 Ban</button></div></div>`).join('')||'<p style="color:#999;">No disputes</p>'}`;}
async function resolveDisp(disputeId,resolution){const d=(await db.collection('disputes').doc(disputeId).get()).data();const o=(await db.collection('orders').doc(d.orderId).get()).data();if(resolution==='refund'){await db.collection('users').doc(o.userId).update({walletBalance:firebase.firestore.FieldValue.increment(o.escrowAmount||o.total),escrowBalance:firebase.firestore.FieldValue.increment(-(o.escrowAmount||o.total))});await db.collection('orders').doc(d.orderId).update({status:'cancelled'});}else{await db.collection('users').doc(o.merchantId).update({walletBalance:firebase.firestore.FieldValue.increment(o.escrowAmount||o.total)});await db.collection('orders').doc(d.orderId).update({status:'completed'});}await db.collection('disputes').doc(disputeId).update({status:'resolved',resolution});toast('Resolved!','success');loadCustomerService();}
async function flagMerchantCS(disputeId){const d=(await db.collection('disputes').doc(disputeId).get()).data();const o=(await db.collection('orders').doc(d.orderId).get()).data();await db.collection('users').doc(o.merchantId).update({isFlagged:true,flaggedUntil:Date.now()+2592000000});toast('Flagged 30 days','success');}
async function requestBanCS(disputeId){const reason=prompt('Reason:');if(!reason)return;const d=(await db.collection('disputes').doc(disputeId).get()).data();const o=(await db.collection('orders').doc(d.orderId).get()).data();await db.collection('ban_requests').add({userId:o.merchantId||o.userId,reason,status:'pending',createdAt:firebase.firestore.FieldValue.serverTimestamp()});toast('Ban requested','success');}

// ============ ADMIN ============
async function loadAdmin(){if(!APP.authenticated||APP.user?.email!==CONFIG.adminEmail){toast('Access denied','error');goTo('home');return;}const c=document.getElementById('admin-content');if(!c)return;c.innerHTML='<p style="text-align:center;">Loading...</p>';try{const[usersSnap,productsSnap,disputesSnap,withdrawalsSnap,banSnap]=await Promise.all([db.collection('users').get(),db.collection('products').get(),db.collection('disputes').where('status','==','open').get(),db.collection('withdrawals').where('status','==','pending').get(),db.collection('ban_requests').where('status','==','pending').get()]);c.innerHTML=`<h3>🔐 Admin</h3><div class="admin-stats-grid"><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FFD700;">${usersSnap.size}</p><p>Users</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#33B5E5;">${productsSnap.size}</p><p>Products</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FF4444;">${disputesSnap.size}</p><p>Disputes</p></div><div class="admin-stat-card"><p style="font-size:28px;font-weight:800;color:#FFBB33;">${withdrawalsSnap.size}</p><p>Withdrawals</p></div></div><h4>🔨 Ban Requests (${banSnap.size})</h4>${banSnap.docs.map(doc=>{const br=doc.data();return`<div style="background:#fff;padding:12px;border-radius:10px;margin-bottom:8px;"><p>User: ${br.userId}</p><p>${br.reason}</p><div style="display:flex;gap:8px;margin-top:8px;"><button class="btn-small-gold" onclick="approveBan('${doc.id}','${br.userId}')">✅ Ban</button><button class="btn-small-gold" style="background:#FF4444;" onclick="rejectBan('${doc.id}')">❌ Reject</button></div></div>`;}).join('')||'<p style="color:#999;">No requests</p>'}<h4>👤 Create CS Account</h4><div class="form-group"><label>Email</label><input type="email" id="cs-email"></div><div class="form-group"><label>Password</label><input type="password" id="cs-password"></div><button class="btn-gold mt-10" onclick="createCSAccount()" style="width:100%;">Create</button><h4>📢 Add Advertiser</h4><div class="form-group"><label>Name</label><input type="text" id="adv-name"></div><div class="form-group"><label>WhatsApp Profile Picture URL</label><input type="text" id="adv-photo"></div><div class="form-group"><label>Rating (1-5)</label><input type="number" id="adv-rating" min="1" max="5" value="5"></div><div class="form-group"><label>Platform (e.g., Instagram, TikTok)</label><input type="text" id="adv-platform"></div><div class="form-group"><label>Platform Handle</label><input type="text" id="adv-handle"></div><div class="form-group"><label>Platform Icon (emoji)</label><input type="text" id="adv-icon" value="📱"></div><div class="form-group"><label>WhatsApp Link</label><input type="text" id="adv-whatsapp"></div><div class="form-group"><label>Description</label><textarea id="adv-desc" rows="2"></textarea></div><button class="btn-gold mt-10" onclick="addAdvertiser()" style="width:100%;">Add Advertiser</button>`;}catch(e){c.innerHTML='<p style="color:red;">Error</p>';}}
async function approveBan(requestId,userId){await db.collection('users').doc(userId).update({isSuspended:true,suspensionCount:firebase.firestore.FieldValue.increment(1)});await db.collection('ban_requests').doc(requestId).update({status:'approved'});toast('Banned','success');loadAdmin();}
async function rejectBan(requestId){await db.collection('ban_requests').doc(requestId).update({status:'rejected'});toast('Rejected','success');loadAdmin();}
async function createCSAccount(){const email=document.getElementById('cs-email')?.value?.trim();const password=document.getElementById('cs-password')?.value?.trim();if(!email||!password){toast('Fill all','error');return;}const username='cs_'+Math.random().toString(36).substring(2,8);await db.collection('users').add({email,password,username,displayName:'Customer Service',accountType:'customerservice',role:'customerservice',createdAt:firebase.firestore.FieldValue.serverTimestamp()});toast('✅ Created! Username: '+username,'success');loadAdmin();}
async function addAdvertiser(){const name=document.getElementById('adv-name')?.value?.trim();const photo=document.getElementById('adv-photo')?.value?.trim();const rating=parseInt(document.getElementById('adv-rating')?.value)||5;const platform=document.getElementById('adv-platform')?.value?.trim();const handle=document.getElementById('adv-handle')?.value?.trim();const icon=document.getElementById('adv-icon')?.value?.trim()||'📱';const whatsapp=document.getElementById('adv-whatsapp')?.value?.trim();const desc=document.getElementById('adv-desc')?.value?.trim();if(!name||!platform||!handle){toast('Fill required fields','error');return;}await db.collection('advertisers').add({name,photoURL:photo||'app-icon.png',rating,platform,handle,platformIcon:icon,whatsappLink:whatsapp||'#',description:desc||'Verified advertising partner',status:'active',createdAt:firebase.firestore.FieldValue.serverTimestamp()});toast('✅ Advertiser added!','success');loadAdmin();}

// ============ DEEP LINKS ============
(function(){const path=window.location.pathname;const pm=path.match(/\/p\/(.+)/);const am=path.match(/\/r\/([^\/]+)\/([^\/]+)/);if(pm)sessionStorage.setItem('deeplink_product',pm[1]);if(am){sessionStorage.setItem('deeplink_product',am[2]);if(db){db.collection('affiliate_products').where('affiliateId','==',am[1]).where('productId','==',am[2]).where('status','==','active').limit(1).get().then(snap=>{if(!snap.empty)db.collection('affiliate_products').doc(snap.docs[0].id).update({clicks:firebase.firestore.FieldValue.increment(1)});});}}})();

// ============ INIT ============
document.addEventListener('DOMContentLoaded',function(){console.log('🚀 Shoplify v2.0');const timer=startLoader();if(!initFirebase()){finishLoader(timer);hideLoader();goTo('onboarding');return;}const params=new URLSearchParams(window.location.search);APP.referralCode=params.get('ref');detectCountry().then(()=>{auth.onAuthStateChanged(async function(user){finishLoader(timer);if(user){APP.user=user;APP.authenticated=true;const doc=await db.collection('users').doc(user.uid).get();if(doc.exists){const p=doc.data();APP.profile=p;APP.accountType=p.accountType||'customer';if(p.loginRestrictedUntil&&p.loginRestrictedUntil>Date.now()||p.isSuspended){auth.signOut();hideLoader();goTo('onboarding');toast('Account restricted.','error');return;}localStorage.setItem('shoplify_auth','true');hideLoader();if(!p.username||!p.password){goTo('setup-credentials');}else{const dp=sessionStorage.getItem('deeplink_product');if(dp){sessionStorage.removeItem('deeplink_product');goTo('product-detail',dp);}else{navigateToDashboard();}}setTimeout(loadNotificationBadge,2000);}else{hideLoader();goTo('account-type');}}else{APP.user=null;APP.authenticated=false;localStorage.removeItem('shoplify_auth');hideLoader();goTo('onboarding');}});});try{const saved=localStorage.getItem('shoplify_cart');if(saved)APP.cart=JSON.parse(saved);}catch(e){}setInterval(()=>{if(APP.cart.length)localStorage.setItem('shoplify_cart',JSON.stringify(APP.cart));},5000);setInterval(()=>{if(APP.authenticated)loadNotificationBadge();},30000);});

// ============ EXPORTS ============
window.goTo=goTo;window.goBack=goBack;window.signInWithGoogle=signInWithGoogle;window.loginWithCredentials=loginWithCredentials;window.selectAccountType=selectAccountType;window.setupCredentials=setupCredentials;window.signOut=signOut;window.filterCat=filterCat;window.filterMarket=filterMarket;window.filterAffProducts=filterAffProducts;window.filterAffCat=filterAffCat;window.selectColor=selectColor;window.selectSize=selectSize;window.updateQty=updateQty;window.addToCart=addToCart;window.buyNow=buyNow;window.shareProductLink=shareProductLink;window.copyText=copyText;window.openModal=openModal;window.closeModal=closeModal;window.toast=toast;window.fmt=fmt;window.showInstallPrompt=showInstallPrompt;window.installProduct=installProduct;window.toggleProduct=toggleProduct;window.markShipped=markShipped;window.sponsorProduct=sponsorProduct;window.confirmSponsor=confirmSponsor;window.selectTemplate=selectTemplate;window.saveStore=saveStore;window.submitProduct=submitProduct;window.previewImgs=previewImgs;window.showDeposit=showDeposit;window.updateDepUSD=updateDepUSD;window.processDeposit=processDeposit;window.showWithdraw=showWithdraw;window.updateWdLocal=updateWdLocal;window.processWithdraw=processWithdraw;window.showAddBank=showAddBank;window.addBank=addBank;window.setPrimaryBank=setPrimaryBank;window.disableBank=disableBank;window.removeCartItem=removeCartItem;window.processCheckout=processCheckout;window.confirmDelivery=confirmDelivery;window.openDispute=openDispute;window.submitDispute=submitDispute;window.resolveDisp=resolveDisp;window.flagMerchantCS=flagMerchantCS;window.requestBanCS=requestBanCS;window.uploadProfilePic=uploadProfilePic;window.changeUname=changeUname;window.saveUname=saveUname;window.changeTheme=changeTheme;window.changeTextSize=changeTextSize;window.subscribeAdvertiser=subscribeAdvertiser;window.approveBan=approveBan;window.rejectBan=rejectBan;window.createCSAccount=createCSAccount;window.addAdvertiser=addAdvertiser;window.loadNotifications=loadNotifications;

console.log('✅ Shoplify v2.0 Complete - All Features Active');
